"""Quick Run 复用已有参数，材料与模型选择必须真实进入请求。"""
import subprocess
import pytest
import json
from pathlib import Path


@pytest.mark.parametrize('requested,profile_ready',[('job-b',True),('missing',True),('job-b',False)])
def test_quick_run_uses_selected_material_and_explicit_model_choice(requested,profile_ready):
    script=r'''
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),ts=require('./ui/node_modules/typescript');
const hooks=[];let index=0,effects=[],tree;const same=(a,b)=>a&&b&&a.length===b.length&&a.every((v,i)=>v===b[i]);
const react={useState(v){const i=index++;if(!hooks[i])hooks[i]={v:typeof v==='function'?v():v};return[hooks[i].v,n=>{hooks[i].v=typeof n==='function'?n(hooks[i].v):n}]},
useMemo(fn,deps){const i=index++;if(!hooks[i]||!same(hooks[i].deps,deps))hooks[i]={v:fn(),deps};return hooks[i].v},useCallback(fn,deps){return react.useMemo(()=>fn,deps)},useRef(v){return react.useMemo(()=>({current:v}),[])},
useEffect(fn,deps){const i=index++;if(!hooks[i]||!same(hooks[i].deps,deps)){hooks[i]={deps};effects.push(fn)}}};
let searchParams=new URLSearchParams({job_profile_id:REQUESTED});const navigations=[];let contentReady=true,deferred=null;
const taskState={tasks:{},start(){},finish(){},fail(){},clear(){}};const calls=[];const api={getProfile:async()=>({profile:{career_status:{ready:PROFILE_READY,reviewed:PROFILE_READY,missing:[]}}}),listEvidence:async(_filters,options)=>options?.cursor?({items:[{evidence_id:'late',title:'后页项目',status:'saved_eligible'}],next_cursor:null}):({next_cursor:'more-evidence',items:[{evidence_id:'actual',title:'实际项目',status:'saved_eligible'},{evidence_id:'extra',title:'额外项目',status:'saved_eligible'},{evidence_id:'old',status:'ready'}]}),listEvidenceMaterialSources:async()=>({items:[{material_id:'sample',label:'样例'},{material_id:'work',label:'工作'}]}),listJobProfiles:async(_filters,options)=>options?.cursor?({items:[{job_profile_id:'job-b',status:'active',title:'指定目标',company:'B公司',source_jd:'完整要求B'}],next_cursor:null}):({items:[{job_profile_id:'job-a',status:'active',title:'另一目标',company:'A公司',source_jd:'完整要求A'}],next_cursor:'second'}),getSettings:async()=>({llm_config:{api_key:{configured:false}}}),
startQuickRun:async payload=>{calls.push(payload);if(deferred)return new Promise(resolve=>deferred.resolve=resolve);return{run_id:'qr_run',status:'DONE',resume_pdf:'outputs/test.pdf',resume_readiness:{content_ready:contentReady,status:contentReady?'NEEDS_REVIEW':'NEEDS_EVIDENCE',reasons:[],gap_tasks:[]},traceability:{evidence_card_ids:['actual'],resume_traceable:true},score_breakdown:{},semantic_review:{mode:'semantic',fit_score:75,resume_score:50,expression_score:88,reviewed_card_count:51,all_requirements_supported:false,requirements:[{requirement_id:'r1',text:'分布式可靠性',status:'partial',resume_status:'not_present',reason:'只有迁移经验',citations:[{fact_id:'actual:actions:0',quote:'幂等重试与故障恢复',source_id:'actual',field:'actions',in_resume:false}]}]}}}};
const exports={},jsx=(type,props)=>typeof type==='function'?type(props||{}):({type,props:props||{}});
const llmConfig={};vm.runInNewContext(ts.transpileModule(fs.readFileSync('ui/src/lib/llmConfig.ts','utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2021}}).outputText,{exports:llmConfig});
const qualityExports={};vm.runInNewContext(ts.transpileModule(fs.readFileSync('ui/src/components/pdf-quality-summary.tsx','utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2021,jsx:ts.JsxEmit.ReactJSX}}).outputText,{exports:qualityExports,require:n=>n==='react/jsx-runtime'?{jsx,jsxs:jsx}:n==='react-i18next'?{useTranslation:()=>({t:k=>k})}:{}});
vm.runInNewContext(ts.transpileModule(fs.readFileSync('ui/src/pages/quick-run/index.tsx','utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2021,jsx:ts.JsxEmit.ReactJSX}}).outputText,
{exports,console,Intl,Date,Map,Set,URLSearchParams,window:{setInterval:()=>0,clearInterval:()=>{}},require:n=>{if(n==='react-router-dom')return{useSearchParams:()=>[searchParams,p=>searchParams=new URLSearchParams(p)],useNavigate:()=>url=>navigations.push(url)};if(n==='react')return react;if(n==='react/jsx-runtime')return{jsx,jsxs:jsx};if(n==='react-i18next')return{useTranslation:()=>({t:k=>k})};if(n==='lucide-react')return new Proxy({},{get:(_,k)=>k});if(n==='@/lib/errors')return{getErrorMessage:e=>String(e)};if(n==='@/lib/llmConfig')return llmConfig;if(n==='@/lib/quick-run-tracker')return{isQuickRunTerminal:s=>['DONE','SKIPPED','FAILED','TIMEOUT','stopped'].includes(s),trackQuickRun:async()=>null};if(n==='@/lib/sidecar/api')return api;if(n==='@/lib/ui')return {notify:()=>{},confirmAction:async()=>true,buttonClass:new Proxy({},{get:()=>''})};if(n==='@/state/task-store')return{useTaskStore:Object.assign(sel=>sel(taskState),{getState:()=>taskState})};if(n==='@/components/pdf-quality-summary')return qualityExports;if(n==='@/components/quality-report')return{QualityReportPanel:()=>null};throw Error(n)}});
const nodes=v=>Array.isArray(v)?v.flatMap(nodes):v&&typeof v==='object'?[v,...nodes(v.props.children)]:[];
const text=v=>Array.isArray(v)?v.map(text).join(' '):v&&typeof v==='object'?text(v.props.children):String(v??'');
async function settle(){for(let i=0;i<8;i++){index=0;tree=exports.QuickRunPage();const pending=effects;effects=[];for(const fn of pending)fn();await Promise.resolve();await Promise.resolve()}}
(async()=>{await settle();const by=id=>nodes(tree).find(n=>n.props['data-testid']===id);
const selected=()=>nodes(tree).find(n=>n.type==='select'&&n.props['aria-label']==='pages.quickRun.selectProfile');
assert.equal(calls.length,0,'导航不得自动生成');assert.equal(selected().props.value,REQUESTED,'不得静默改为列表首项');
if(REQUESTED==='missing'||!PROFILE_READY){assert.ok(nodes(tree).find(n=>n.props['data-automation-id']==='quick-run-start').props.disabled);assert.ok(text(tree).includes(REQUESTED==='missing'?'pages.quickRun.targetUnavailable':'pages.quickRun.profileRequired'));return;}
let select=nodes(tree).find(n=>n.type==='select'&&n.props['aria-label']==='pages.quickRun.materialSource');assert.ok(select,'材料必须可选');select.props.onChange({target:{value:'work'}});await settle();
const extra=nodes(tree).find(n=>n.props['data-evidence-id']==='extra');assert.ok(extra,'缺少复用evidence_ids的选材入口');extra.props.onChange({target:{checked:false}});await settle();
let start=()=>nodes(tree).find(n=>n.type==='button'&&text(n).includes('pages.quickRun.start'));assert.equal(start().props.disabled,false,'第二页的有效目标也应可启动');await start().props.onClick();await settle();
assert.equal(calls[0].job_profile_id,'job-b');assert.ok(text(tree).includes('分布式可靠性'));assert.ok(text(tree).includes('幂等重试与故障恢复'));assert.ok(text(tree).includes('pages.quickRun.semantic.status.not_present'));assert.ok(text(tree).includes('quality.expression'));assert.equal(calls[0].options.timeout_seconds,1800);assert.ok(by('quick-run-prepare-pdf'));by('quick-run-prepare-pdf').props.onClick();assert.equal(navigations.at(-1),'/submissions?quick_run_id=qr_run');
assert.equal(calls[0].options.material_id,'work');assert.equal(calls[0].options.use_llm,true);assert.equal(calls[0].options.require_llm,true);assert.deepEqual(Array.from(calls[0].options.evidence_ids),['actual','late']);
let toggle=nodes(tree).find(n=>n.type==='input'&&n.props.type==='checkbox');toggle.props.onChange({target:{checked:false}});await settle();assert.ok(!by('quick-run-prepare-pdf'),'改输入即清旧结果');contentReady=false;await start().props.onClick();await settle();assert.equal(calls[1].options.require_llm,false);assert.ok(!by('quick-run-prepare-pdf'),'DONE不代表完整内容');
const originalStart=api.startQuickRun;api.startQuickRun=async()=>({run_id:'skip',status:'SKIPPED',failed_step:'matching-scoring',reason:'matching_excluded',career_direction:{status:'excluded',reason:'岗位方向不符',preference:{text:'产品平台'},jd_quote:'电路设计'},resume_readiness:{status:'NOT_GENERATED',content_ready:false,reasons:['本次未生成简历'],gap_tasks:[]}});
await start().props.onClick();await settle();assert.ok(text(tree).includes('pages.quickRun.notGenerated'));assert.equal(nodes(tree).filter(n=>n.type==='p'&&text(n)==='pages.quickRun.result').length,1,'跳过匹配后不得把生成和评测标为已生成');assert.ok(!text(tree).includes('pages.quickRun.needsReview'));assert.ok(!by('quick-run-prepare-pdf'));api.startQuickRun=originalStart;
deferred={};await start().props.onClick();await settle();assert.ok(selected().props.disabled);searchParams=new URLSearchParams({job_profile_id:'job-a'});await settle();deferred.resolve({run_id:'late-old-run',status:'DONE',resume_pdf:'old.pdf',resume_readiness:{content_ready:true,reasons:[],gap_tasks:[]},traceability:{evidence_card_ids:['actual'],resume_traceable:true}});await settle();assert.equal(selected().props.value,'job-a');assert.ok(!by('quick-run-prepare-pdf'),'晚到旧目标响应不应覆盖新选择');
})().catch(e=>{console.error(e);process.exitCode=1});
'''
    script=script.replace('REQUESTED',json.dumps(requested)).replace('PROFILE_READY',str(profile_ready).lower())
    result=subprocess.run(['node','-e',script],cwd=Path(__file__).resolve().parents[3],capture_output=True,text=True,timeout=30)
    assert result.returncode==0,result.stdout+result.stderr
